static TestResult test_gpuaddr_tiling_1dthin(void) {
	const size_t surfsize = sizeof(s_detiledsurface);
	static uint8_t tiledsurf[sizeof(s_detiledsurface)] = {0};

	const GpaTilingParams srctp = {
	    .tilemode = GNM_TM_DISPLAY_LINEAR_GENERAL,
	    .mingpumode = GNM_GPU_BASE,

	    .linearwidth = 32,
	    .linearheight = 32,
	    .lineardepth = 1,
	    .numfragsperpixel = 1,
	    .basetiledpitch = 32,

	    .miplevel = 0,
	    .arrayslice = 0,
	    .bitsperfrag = 32,
	    .surfaceflags = {0},
	    .isblockcompressed = false,
	};
	const GpaTilingParams dst_tp = {
	    .tilemode = GNM_TM_THIN_1D_THIN,
	    .mingpumode = GNM_GPU_BASE,

	    .linearwidth = 32,
	    .linearheight = 32,
	    .lineardepth = 1,
	    .numfragsperpixel = 1,
	    .basetiledpitch = 32,

	    .miplevel = 0,
	    .arrayslice = 0,
	    .bitsperfrag = 32,
	    .surfaceflags = {0},
	    .isblockcompressed = false,
	};

	GpaError err = gpaTileSurface(
	    tiledsurf, surfsize, s_detiledsurface, surfsize, &srctp, &dst_tp
	);
	utassert(err == GPA_ERR_OK);
	utassert(memcmp(s_tiledsurface, tiledsurf, surfsize) == 0);

	return test_success();
}

