static TestResult test_gpuaddr_reformat_bc7_r8g8b8a8(void) {
	static uint8_t detiledsurf[sizeof(s_bc7surface)] = {0};

	GpaTextureInfo texinfo = {
	    .type = GNM_TEXTURE_2D,
	    .fmt = GNM_FMT_BC7_SRGB,

	    .width = 32,
	    .height = 32,
	    .depth = 1,
	    .pitch = 8,

	    .numfrags = 1,
	    .nummips = 1,
	    .numslices = 1,

	    .tm = GNM_TM_THIN_1D_THIN,
	    .mingpumode = GNM_GPU_BASE,
	};
	GpaTilingParams tp = {0};
	GpaError err = gpaTpInit(&tp, &texinfo, 0, 0);
	utassert(err == GPA_ERR_OK);

	GpaTilingParams dst_tp = tp;
	dst_tp.tilemode = GNM_TM_DISPLAY_LINEAR_GENERAL;

	err = gpaTileSurface(
	    detiledsurf, sizeof(detiledsurf), s_bc7surface,
	    sizeof(s_bc7surface), &tp, &dst_tp
	);
	utassert(err == GPA_ERR_OK);

	texinfo.tm = GNM_TM_DISPLAY_LINEAR_GENERAL;

	static uint8_t convertedsurf[sizeof(s_rgba8surf)] = {0};

	uint64_t decsize = 0;
	err = gpaGetDecompressedSize(&decsize, &texinfo);
	utassert(err == GPA_ERR_OK);
	utassert(decsize == sizeof(convertedsurf));

	err = gpaDecompressTexture(
	    convertedsurf, sizeof(convertedsurf), detiledsurf,
	    sizeof(detiledsurf), &texinfo, NULL
	);
	utassert(err == GPA_ERR_OK);

	FILE* h = fopen("surf.bin", "w");
	fwrite(convertedsurf, 1, sizeof(convertedsurf), h);
	fclose(h);

	utassert(
	    memcmp(s_rgba8surf, convertedsurf, sizeof(convertedsurf)) == 0
	);

	return test_success();
}

