static TestResult test_gpuaddr_reformat_bc6_r16g16b16a16(void) {
	static uint8_t detiledsurf[sizeof(s_bc6surface)] = {0};

	GpaTextureInfo texinfo = {
	    .type = GNM_TEXTURE_2D,
	    .fmt = GNM_FMT_BC6_UNORM,

	    .width = 64,
	    .height = 32,
	    .depth = 1,
	    .pitch = 16,

	    .numfrags = 1,
	    .nummips = 1,
	    .numslices = 1,

	    .tm = GNM_TM_THIN_1D_THIN,
	    .mingpumode = GNM_GPU_BASE,
	};
	GpaTilingParams tp = {0};
	GpaError err = gpaTpInit(&tp, &texinfo, 0, 0);
	utassert(err == GPA_ERR_OK);

	GpaTilingParams dst_tp = tp;
	dst_tp.tilemode = GNM_TM_DISPLAY_LINEAR_GENERAL;

	err = gpaTileSurface(
	    detiledsurf, sizeof(detiledsurf), s_bc6surface,
	    sizeof(s_bc6surface), &tp, &dst_tp
	);
	utassert(err == GPA_ERR_OK);

	texinfo.tm = GNM_TM_DISPLAY_LINEAR_GENERAL;

	static uint8_t convertedsurf[sizeof(s_rgba16surf)] = {0};

	uint64_t decsize = 0;
	err = gpaGetDecompressedSize(&decsize, &texinfo);
	utassert(err == GPA_ERR_OK);
	utassert(decsize == sizeof(convertedsurf));

	err = gpaDecompressTexture(
	    convertedsurf, sizeof(convertedsurf), detiledsurf,
	    sizeof(detiledsurf), &texinfo, NULL
	);
	utassert(err == GPA_ERR_OK);
	utassert(
	    memcmp(s_rgba16surf, convertedsurf, sizeof(convertedsurf)) == 0
	);

	return test_success();
}

// TODO: move this somewhere else?
static TestResult test_gpuaddr_drtbytezsize(void) {
	const GnmDepthRenderTarget desc = {
	    .zinfo = {.asuint = 34547},
	    .stencilinfo = {.asuint = 537927680},
	    .zreadbase256b = 33614080,
	    .stencilreadbase256b = 0,
	    .zwritebase256b = 33614080,
	    .stencilwritebase256b = 0,
	    .depthsize = {.asuint = 293103},
	    .depthslice = {.asuint = 0},
	    .depthview = {.asuint = 0},
	    .htiledatabase256b = 0,
	    .htilesurface = {.asuint = 0},
	    .depthinfo = {.asuint = 1739840},
	    .size = {.asuint = 0},
	};

	uint64_t zsize = 0;
	GnmError err = gnmDrtCalcByteSize(&zsize, NULL, &desc);
	utassert(err == GNM_ERROR_OK);
	utassert(zsize == 0x900000);

	return test_success();
}

bool runtests_gpuaddr(uint32_t* passedtests) {
	const TestUnit tests[] = {
	    {.fn = &test_gpuaddr_tiling_1dthin,
	     .name = "Tiling 1D thin surface test"},
	    {.fn = &test_gpuaddr_detiling_1dthin,
	     .name = "Detiling 1D thin surface test"},
	    {.fn = &test_gpuaddr_reformat_bc7_r8g8b8a8,
	     .name = "Reformat BC7 to R8G8B8A8 test"},
	    {.fn = &test_gpuaddr_reformat_bc6_r16g16b16a16,
	     .name = "Reformat BC6h to R16G16B16A16 test"},
	    {.fn = &test_gpuaddr_drtbytezsize, .name = "DRT Z size test"},
	};

	for (uint32_t i = 0; i < uasize(tests); i++) {
		if (!test_run(&tests[i])) {
			return false;
		}
		*passedtests += 1;
	}

	return true;
}
